--- Fitting rail track to a line, from the game's own rail planner data
--- (rail_data.lua, generated by tests/gen-rail-data.sh).
---
--- Track is a chain of rail ends: at an end facing direction d (16 directions),
--- the rail planner offers three pieces: straight on, or turning one step left or
--- right. Each piece's other end ("goal") is where the next one attaches. The fit
--- starts at the line's start, snapped to the rail grid, and at every step tries
--- every sequence of the next DEPTH pieces, scoring how far their ends land from
--- the line and how far their direction is from the line's; the first piece of the
--- best sequence is laid. Plain functions on data (no game API).
local data = require("scripts.build.rail_data")

local lib = {}

--- Pieces looked ahead per step.
lib.DEPTH = 4
--- Weight of a direction error (radians squared) against a distance error (tiles squared).
lib.ANGLE_WEIGHT = 3
--- Pieces laid without getting further along the line before giving up.
lib.STALL = 15

--- Ends further than this (tiles) from the line are reported (the line bends more
--- tightly than rails can).
lib.TOLERANCE = 1.5

--- @class TrackEnd
--- @field x number
--- @field y number
--- @field direction integer  # 0..15, the way the end faces (out of its rail)

--- @class RailPiece
--- @field name string
--- @field x number
--- @field y number
--- @field direction integer
--- @field from TrackEnd   # the end it attaches to
--- @field goal TrackEnd   # its other end

--- The extensions at an end facing `direction` (relative to the end).
--- @param direction integer
local function extensions(direction)
    local by_parity = data.ends[direction]
    local _, entry = next(by_parity)
    return entry.extensions
end

--- Signal locations at an end facing `direction` (relative to the end).
--- @param direction integer
--- @return table<string, {x: number, y: number, direction: integer}>
function lib.signals(direction)
    local _, entry = next(data.ends[direction])
    return entry.signals
end

--- The tiles a piece covers, relative to its position.
--- @param name string
--- @param direction integer
--- @return integer[][]
function lib.cells(name, direction)
    return data.cells[name .. "/" .. direction] or {}
end

--- The parity (x % 2, y % 2) rail ends facing `direction` have.
--- @param direction integer
--- @return integer, integer
local function parity(direction)
    local key = next(data.ends[direction])
    local px, py = key:match("(%d),(%d)")
    return tonumber(px), tonumber(py)
end

--- @param direction integer
--- @return number, number  # unit vector (map y down)
function lib.unit(direction)
    local a = direction / 16 * 2 * math.pi
    return math.sin(a), -math.cos(a)
end

--- The direction (0..15) nearest to a vector.
local function direction_of(vx, vy)
    local a = math.atan2(vx, -vy)
    return math.floor(a / (2 * math.pi / 16) + 0.5) % 16
end

--- A rail end near `p`, facing along (tx, ty), on the rail grid.
--- @return TrackEnd
function lib.start(p, tx, ty)
    local d = direction_of(tx, ty)
    local px, py = parity(d)
    local function snap(v, par) return math.floor((v - par) / 2 + 0.5) * 2 + par end
    return { x = snap(p.x, px), y = snap(p.y, py), direction = d }
end

--- @class RailLine
--- @field xs number[]
--- @field ys number[]
--- @field tx number[]   # unit tangent
--- @field ty number[]
--- @field n integer

--- Nearest line point to (x, y), searching around `hint` (the fit moves forward).
--- @param line RailLine
--- @return integer index, number distance
local function nearest(line, x, y, hint)
    local best, best_d = hint, math.huge
    for i = math.max(1, hint - 8), math.min(line.n, hint + 40) do
        local dx, dy = line.xs[i] - x, line.ys[i] - y
        local d = dx * dx + dy * dy
        if d < best_d then best, best_d = i, d end
    end
    -- Past either end, measure to the line carried on straight: otherwise looking
    -- ahead beyond the end pulls everything towards the end point, and the fit
    -- keeps putting off turns there.
    if best == line.n or best == 1 then
        local tx, ty = line.tx[best], line.ty[best]
        local rx, ry = x - line.xs[best], y - line.ys[best]
        local along = rx * tx + ry * ty
        if (best == line.n and along > 0) or (best == 1 and along < 0) then
            local side = rx * ty - ry * tx
            return best, math.abs(side)
        end
    end
    return best, math.sqrt(best_d)
end

--- Smallest angle between direction d and the line's tangent at i.
local function angle_error(line, i, d)
    local ux, uy = lib.unit(d)
    local dot = ux * line.tx[i] + uy * line.ty[i]
    return math.acos(math.max(-1, math.min(1, dot)))
end

--- Cost of following `depth` pieces from `loc` (best over all sequences), and the
--- first piece of the best sequence.
--- @return number cost, table|nil first, integer hint
local function search(line, loc, hint, depth)
    if depth == 0 then return 0, nil, hint end
    local best_cost, best_first, best_hint = math.huge, nil, hint
    for _, ext in ipairs(extensions(loc.direction)) do
        local goal = { x = loc.x + ext.goal.x, y = loc.y + ext.goal.y, direction = ext.goal.direction }
        local i, dist = nearest(line, goal.x, goal.y, hint)
        local cost = dist * dist + lib.ANGLE_WEIGHT * angle_error(line, i, goal.direction) ^ 2
        if i < hint - 2 then cost = cost + 20 end -- going back along the line
        if cost < best_cost then
            local rest = search(line, goal, i, depth - 1)
            cost = cost + rest
            if cost < best_cost then best_cost, best_first, best_hint = cost, ext, i end
        end
    end
    return best_cost, best_first, best_hint
end

--- @class RailFit
--- @field loc TrackEnd
--- @field hint integer
--- @field pieces RailPiece[]
--- @field off TrackEnd[]     # ends further than TOLERANCE from the line
--- @field done boolean
--- @field start TrackEnd

--- @param line RailLine
--- @param opts {elevated: boolean|nil, ramps: boolean|nil}|nil
---   elevated: elevated rails (needing supports); ramps: a ramp up at the start and
---   down at the end (they only go straight: the start is turned to the nearest
---   straight direction)
--- @return RailFit
function lib.new_fit(line, opts)
    opts = opts or {}
    local tx, ty = line.tx[1], line.ty[1]
    local ramps = opts.elevated and opts.ramps and data.ramps and next(data.ramps.up) ~= nil
    if ramps then
        local d = math.floor(direction_of(tx, ty) / 4 + 0.5) % 4 * 4
        tx, ty = lib.unit(d)
    end
    local start = lib.start({ x = line.xs[1], y = line.ys[1] }, tx, ty)
    local fit = { loc = start, start = start, hint = 1, pieces = {}, off = {}, done = line.n < 2,
        elevated = opts.elevated == true, ramps = ramps }
    if ramps and not fit.done then
        local up = data.ramps.up[start.direction]
        if up then lib.lay(fit, line, up) end
    end
    return fit
end

--- The pieces (at most `depth`) leading to a straight-facing end and then a ramp
--- down landing within `reach` of the line's end (default 4 tiles), staying
--- closest to the line; nil if none.
--- @return table[]|nil path, number worst
local function ramp_down(fit, line, depth, reach)
    reach = reach or 4
    local ex, ey = line.xs[line.n], line.ys[line.n]
    local best_path, best_cost, best_worst = nil, math.huge, math.huge
    local path = {}
    local function walk(at, left, cost, worst, h)
        local down = at.direction % 4 == 0 and data.ramps.down[at.direction]
        if down then
            local gx, gy = at.x + down.goal.x, at.y + down.goal.y
            local _, mid = nearest(line, at.x + down.x, at.y + down.y, h)
            local land = math.sqrt((gx - ex) ^ 2 + (gy - ey) ^ 2)
            local total = cost + mid * mid + land * land
            if land <= reach and total < best_cost then
                best_cost, best_worst = total, math.max(worst, mid)
                best_path = {}
                for i, ext in ipairs(path) do best_path[i] = ext end
                best_path[#best_path + 1] = down
            end
        end
        if left == 0 or cost >= best_cost then return end
        for _, ext in ipairs(extensions(at.direction)) do
            local goal = { x = at.x + ext.goal.x, y = at.y + ext.goal.y, direction = ext.goal.direction }
            local i, dist = nearest(line, goal.x, goal.y, h)
            path[#path + 1] = ext
            walk(goal, left - 1, cost + dist * dist, math.max(worst, dist), math.max(h, i))
            path[#path] = nil
        end
    end
    walk(fit.loc, depth, 0, 0, fit.hint)
    return best_path, best_worst
end

--- The fit is done. Elevated track with ramps that hasn't come down yet ramps down
--- from here, even if the ramp runs on past the line's end (the line kept bending
--- until too near its end for a ramp to land there).
local function finish(fit, line)
    fit.done = true
    if fit.ramps and not fit.ramped_down then
        local path = ramp_down(fit, line, 5, math.huge)
        if path then
            for _, ext in ipairs(path) do lib.lay(fit, line, ext, lib.TOLERANCE * 2) end
            fit.ramped_down = true
        end
    end
end

--- Lay the next piece. On a closed line, near the end, look for pieces that meet
--- the start exactly.
--- @param fit RailFit
--- @param line RailLine
--- @param closed boolean
--- @return number used  # work units
function lib.step(fit, line, closed)
    if fit.done then return 0 end
    local loc = fit.loc
    -- Elevated with ramps: once within reach of the end, ramp down there.
    if fit.ramps and fit.hint > line.n - 28 then
        local path, worst = ramp_down(fit, line, 5)
        if path and (worst <= lib.TOLERANCE * 2 or fit.hint >= line.n - 20) then
            for _, ext in ipairs(path) do lib.lay(fit, line, ext, lib.TOLERANCE * 2) end
            fit.ramped_down = true
            fit.done = true
            return 3 ^ 5
        end
    end
    -- Reached the end of the line?
    local ex, ey = line.xs[line.n], line.ys[line.n]
    local ux, uy = line.tx[line.n], line.ty[line.n]
    -- (past the end along its tangent counts only near the end: a curve can end
    -- pointing back across its own middle)
    local near_end = fit.hint >= line.n - 12 and (loc.x - ex) ^ 2 + (loc.y - ey) ^ 2 < 144
    if fit.hint >= line.n - 2 or (near_end and (loc.x - ex) * ux + (loc.y - ey) * uy >= -0.5) then
        finish(fit, line)
        return 3 ^ 5
    end
    if closed and fit.hint > line.n - 60 and #fit.pieces > 4 then
        -- Near the end of a loop: the best way to meet the start exactly, taken
        -- once it stays close to the line (or when the line runs out).
        local path, worst = lib.close(loc, fit.start, lib.CLOSE_DEPTH, line, fit.hint)
        if path and (worst <= lib.TOLERANCE or fit.hint >= line.n - 4) then
            for _, ext in ipairs(path) do lib.lay(fit, line, ext) end
            fit.closed = true
            fit.done = true
            return 3 ^ lib.CLOSE_DEPTH
        end
    end
    -- Track that stops moving along the line (it can't follow a hairpin, or the
    -- line runs back over itself) ends here.
    if #fit.pieces > 2 * line.n + 20 or (#fit.pieces - (fit.progress_at or 0)) > lib.STALL then
        fit.stalled = true
        fit.done = true
        return 1
    end
    local _, first = search(line, loc, fit.hint, lib.DEPTH)
    if not first then
        fit.done = true
        return 1
    end
    -- At the end of the line: stop once another piece would only get further from it.
    if fit.hint >= line.n - 12 then
        local now = (loc.x - ex) ^ 2 + (loc.y - ey) ^ 2
        local gx, gy = loc.x + first.goal.x, loc.y + first.goal.y
        if (gx - ex) ^ 2 + (gy - ey) ^ 2 >= now then
            finish(fit, line)
            return 3 ^ 5
        end
    end
    local before = fit.hint
    lib.lay(fit, line, first)
    if fit.hint > before then fit.progress_at = #fit.pieces end
    return 3 ^ lib.DEPTH
end

--- Add a piece at the current end; an end further than `tolerance` (default
--- TOLERANCE) from the line is reported.
function lib.lay(fit, line, ext, tolerance)
    local loc = fit.loc
    local goal = { x = loc.x + ext.goal.x, y = loc.y + ext.goal.y, direction = ext.goal.direction }
    local name = ext.name
    if fit.elevated and name ~= "rail-ramp" then name = "elevated-" .. name end
    fit.pieces[#fit.pieces + 1] = {
        name = name, ground_name = ext.name, x = loc.x + ext.x, y = loc.y + ext.y, direction = ext.direction,
        from = { x = loc.x, y = loc.y, direction = loc.direction }, goal = goal,
    }
    local i, dist = nearest(line, goal.x, goal.y, fit.hint)
    if dist > (tolerance or lib.TOLERANCE) then fit.off[#fit.off + 1] = goal end
    fit.hint = math.max(fit.hint, i)
    fit.loc = goal
end

--- Where elevated track needs supports: at joints, each where the track would
--- otherwise run out of reach of the last support (or of a ramp's top).
--- @param fit RailFit
--- @return TrackEnd[]
function lib.supports(fit)
    local range = (data.support and data.support.range or 11) - 1
    local ramp_range = (data.support and data.support.ramp_range or 9) - 1
    local out = {}
    local last, reach = nil, 0
    for k, piece in ipairs(fit.pieces) do
        if piece.ground_name == "rail-ramp" then
            -- a ramp carries the track a little past its top
            -- going up the ramp faces the way it climbs (its top is the goal);
            -- going down it faces back (its top is where it starts)
            local top = piece.goal.direction == piece.direction and piece.goal or piece.from
            last, reach = top, ramp_range
        else
            if not last then
                out[#out + 1] = piece.from
                last, reach = piece.from, range
            end
            local g = piece.goal
            local nxt = fit.pieces[k + 1]
            if not (nxt and nxt.ground_name == "rail-ramp") and math.sqrt((g.x - last.x) ^ 2 + (g.y - last.y) ^ 2) > reach then
                out[#out + 1] = g
                last, reach = g, range
            end
        end
    end
    return out
end

--- Pieces looked ahead when closing a loop.
lib.CLOSE_DEPTH = 8

--- The pieces (at most `depth`) leading from `loc` exactly to `target` that stay
--- closest to the line, and how far they stray at worst; nil if there are none.
--- @return table[]|nil path, number worst
function lib.close(loc, target, depth, line, hint)
    local best_path, best_cost, best_worst = nil, math.huge, math.huge
    local path = {}
    local function walk(at, left, cost, worst, h)
        if at.x == target.x and at.y == target.y and at.direction == target.direction then
            if cost < best_cost then
                best_cost, best_worst = cost, worst
                best_path = {}
                for i, ext in ipairs(path) do best_path[i] = ext end
            end
            return
        end
        if left == 0 or cost >= best_cost then return end
        -- Each piece moves at most ~6 tiles: prune what can't get there.
        local dx, dy = target.x - at.x, target.y - at.y
        if dx * dx + dy * dy > (left * 6) ^ 2 then return end
        for _, ext in ipairs(extensions(at.direction)) do
            local goal = { x = at.x + ext.goal.x, y = at.y + ext.goal.y, direction = ext.goal.direction }
            local i, dist = nearest(line, goal.x, goal.y, h)
            path[#path + 1] = ext
            walk(goal, left - 1, cost + dist * dist, math.max(worst, dist), math.max(h, i))
            path[#path] = nil
        end
    end
    walk(loc, depth, 0, 0, hint)
    return best_path, best_worst
end

return lib
